SELECT ts.id, ts.symbol, ts.interval_code, ts.decision, ts.total_score, ts.confidence_score, ts.market_regime, ts.selected_strategy, ts.final_entry_allowed, ts.candle_open_time AS candle_open_ksa, CONVERT_TZ(ts.candle_open_time, '+03:00', '+00:00') AS candle_open_utc, ts.generated_at AS generated_ksa, CONVERT_TZ(ts.generated_at, '+03:00', '+00:00') AS generated_utc, ts.created_at AS created_ksa, CONVERT_TZ(ts.created_at, '+03:00', '+00:00') AS created_utc, ts.latest_price, ts.stop_loss, ts.take_profit, ts.risk_reward_ratio FROM trade_signal ts WHERE ts.id = 89469